namespace Atc.Rest.Api.Generator;

/// <summary>
/// The rules the generators report themselves (the configuration, the project, the generation), each with its
/// title, its message (with <c>{0}</c>-style arguments) and its default severity - one source for the Roslyn
/// descriptors and for every reader of the rules. The specification rules the validator reports carry their
/// message and severity in the diagnostic itself.
/// </summary>
public static class RuleCatalog
{
    /// <summary>
    /// Gets the rules by id.
    /// </summary>
    public static IReadOnlyDictionary<string, RuleDefinition> Rules { get; } = new Dictionary<string, RuleDefinition>(StringComparer.Ordinal)
    {
        [RuleIdentifiers.ServerGenerationError] = new("OpenAPI Generation Error", "Failed to generate API from {0}: {1}", DiagnosticSeverity.Error),
        [RuleIdentifiers.ServerParsingError] = new("OpenAPI Parsing Error", "Failed to parse OpenAPI document from {0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.ClientGenerationError] = new("OpenAPI Client Generation Error", "Failed to generate API client from {0}: {1}", DiagnosticSeverity.Error),
        [RuleIdentifiers.ClientParsingError] = new("OpenAPI Client Parsing Error", "Failed to parse OpenAPI document for client from {0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.HandlerScaffoldGenerationError] = new("Handler Scaffold Generation Error", "Failed to generate handler scaffolds from {0}: {1}", DiagnosticSeverity.Error),
        [RuleIdentifiers.DomainParsingError] = new("OpenAPI Parsing Error for Domain Generator", "Failed to parse OpenAPI document from {0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.OutputDirectoryNotSpecified] = new("Output Directory Not Specified", "Cannot generate handler scaffolds: no marker file found and no outputPath configured", DiagnosticSeverity.Warning),
        [RuleIdentifiers.ServerRequiresAspNetCore] = new("ASP.NET Core References Required", "The .atc-rest-api-server marker file requires ASP.NET Core references. Add a reference to Microsoft.AspNetCore.App or remove the marker file.", DiagnosticSeverity.Error),
        [RuleIdentifiers.MarkerNamespaceRewritten] = new("The marker's namespace was rewritten", "The marker's namespace '{0}' is no C# namespace: the generated code is in '{1}'. Write that in the marker to say what is generated.", DiagnosticSeverity.Info),
        [RuleIdentifiers.ReadEnumMemberNamesOn] = new("readEnumMemberNames is on", "readEnumMemberNames is on in '{0}': string enums are also read by their C# member names, as a peer built on 2.x wrote them. Remove it once no such peer is left - until then a peer that sends a member name instead of the specification's value is not told.", DiagnosticSeverity.Info),
        [RuleIdentifiers.RequestDelegateGeneratorDoesNotSeeTheEndpoints] = new("The Request Delegate Generator does not see the generated endpoints", "EnableRequestDelegateGenerator is on (PublishAot sets it), but the Request Delegate Generator does not see the endpoints this generator emits - one source generator's output is not another's input. They are bound by reflection at run time (RequestDelegateFactory), which trimming and Native AOT do not support, and the build's trim and AOT analysis does not report it. A Native AOT server is not supported yet.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.RootNamespaceBindsToAnAspNetCoreName] = new("The root namespace names an ASP.NET Core type or namespace", "The root namespace '{0}' starts with '{1}', which inside Microsoft.AspNetCore.Http.Generated is {2}. The Request Delegate Generator writes an [AsParameters] type without 'global::' there, so its generated code does not compile (CS0426) for an endpoint with parameters whose types are in this namespace. Give the project another root namespace (the marker's 'namespace', or the name of the specification file).", DiagnosticSeverity.Warning),
        [RuleIdentifiers.DomainRequiresAspNetCore] = new("ASP.NET Core References Required", "The .atc-rest-api-server-handlers marker file requires ASP.NET Core references. Add a reference to Microsoft.AspNetCore.App or remove the marker file.", DiagnosticSeverity.Error),
        [RuleIdentifiers.EndpointInjectionGenerationError] = new("Endpoint Injection Generation Error", "Failed to generate endpoint injection for {0}: {1}", DiagnosticSeverity.Error),
        [RuleIdentifiers.NoEndpointsFoundForInjection] = new("No Endpoints Found for Injection", "No endpoint interfaces found matching project name '{0}'. Ensure the client generator has run and generated endpoints in namespace '{0}.Generated.*.Endpoints.Interfaces'.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.GenerationSummary] = new("ATC API Generation Summary", "{0}", DiagnosticSeverity.Info),
        [RuleIdentifiers.ContractsNamespaceAmbiguous] = new("Contracts Namespace Cannot Be Auto-Detected", "Cannot auto-detect contracts namespace for Domain project '{0}'. Multiple sibling .atc-rest-api-server markers exist and none match the directory-name convention (<X>.Domain ↔ <X>.Contracts). Set 'contractsNamespace' explicitly in .atc-rest-api-server-handlers.", DiagnosticSeverity.Error),
        [RuleIdentifiers.HandlerStubShadowed] = new("Handler Stub Shadowed by User Handler", "Handler '{0}' is implemented in '{1}' and also has a leftover scaffolded stub in '{2}'. The user handler is registered; delete the stub to avoid confusion.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.MarkerConfigParseError] = new("Marker File Could Not Be Read", "The marker file '{0}' could not be read: {1}. Nothing is generated until it is fixed.", DiagnosticSeverity.Error),
        [RuleIdentifiers.MultipleMarkerFiles] = new("More Than One Marker File", "The project has {0} '{1}' marker files ({2}); the generator takes one configuration per project. Nothing is generated until one is left.", DiagnosticSeverity.Error),
        [RuleIdentifiers.MultipleSpecifications] = new("More Than One Specification", "The project has {0} specifications ({1}); the generator reads one specification per project, with its parts named '{2}_{{Part}}.yaml'. Nothing is generated until one is left.", DiagnosticSeverity.Error),
        [RuleIdentifiers.MarkerConfigUnknownSetting] = new("Unknown Marker File Setting", "The marker file '{0}': {1}", DiagnosticSeverity.Warning),
        [RuleIdentifiers.OverlayNotFound] = new("Overlay Not Found", "The marker file '{0}' lists the overlay '{1}', which is not an AdditionalFiles item of the project (add <AdditionalFiles Include=\"{1}\" /> next to the specification's); nothing is generated", DiagnosticSeverity.Error),
        [RuleIdentifiers.OverlayInvalid] = new("Overlay Cannot Be Applied", "The overlay '{0}'{1} cannot be applied, so nothing is generated: {2}", DiagnosticSeverity.Error),
        [RuleIdentifiers.OverlayTargetSelectsNothing] = new("Overlay Target Selects Nothing", "The overlay '{0}'{1} changes nothing - has the specification changed (a renamed path or schema)? {2}", DiagnosticSeverity.Warning),
        [RuleIdentifiers.ValidationBadRequestDeclaredAsString] = new("Validation 400 Declared As String", "'{0}' declares its 400 as a string, but the ValidationFilter answers an invalid request with a ValidationProblemDetails (application/problem+json): the client reads its title as the string, and the field errors are only in the response content. Declare the 400 as ValidationProblemDetails to keep them typed, or remove the 400's content (the 400 is then the problem). Either changes a published client's BadRequestContent from the string to the problem: check what its consumers read first.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.HandlerScaffoldNotWritten] = new("Handler Scaffold Not Written", "The handler scaffold '{0}' cannot be written to '{1}': {2}. It is part of this build, but no file is created; check \"generateHandlersOutput\" and the folder.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.HandlerNotImplemented] = new("Handler Not Implemented", "The operation's handler '{0}' is not implemented: the scaffold that answers 501 is part of this build, but '{1}' is not written because AtcRestApiScaffoldHandlers is false (a CI build). Build the project where the scaffolds are written, and commit the handler.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.OverlayNotListed] = new("Overlay Not Listed", "'{0}' is an overlay, but the marker file '{1}' does not list it in \"overlays\", so it is not applied", DiagnosticSeverity.Info),
        [RuleIdentifiers.ClientRequiresAtcRestClient] = new("Atc.Rest.Client Reference Required", "The EndpointPerOperation generation mode requires a reference to the Atc.Rest.Client NuGet package. Add a reference to Atc.Rest.Client or change generationMode to TypedClient.", DiagnosticSeverity.Error),
        [RuleIdentifiers.AtcRestClientTooOld] = new("Atc.Rest.Client Version Too Old", "The EndpointPerOperation generation mode requires Atc.Rest.Client {0} or later, and the project references {1}. Update the Atc.Rest.Client package reference.", DiagnosticSeverity.Error),
        [RuleIdentifiers.MinimalApiTooOld] = new("Atc.Rest.MinimalApi Version Too Old", "The generated server builds on Atc.Rest.MinimalApi {0} or later (its validation keys, a handler's ValidationException with its field errors, its problem bodies, the validation of a form endpoint's request), and the project references {1}. Update the Atc.Rest.MinimalApi package reference, or turn useMinimalApiPackage, useValidationFilter and useGlobalErrorHandler off in the marker.", DiagnosticSeverity.Error),
        [RuleIdentifiers.TypedClientRequiresAtcRestClient] = new("Atc.Rest.Client Reference Required", "The TypedClient uses Atc.Rest.Client for {0}. Add a reference to the Atc.Rest.Client NuGet package (2.7.0 or later).", DiagnosticSeverity.Error),
        [RuleIdentifiers.SignalRClientPackageRecommended] = new("SignalR Client Package Not Referenced", "The specification declares {0} SignalR hub(s) with x-signalr-hubs, and the project does not reference Microsoft.AspNetCore.SignalR.Client: the typed hub client(s) ({1}) are not generated. Add the package reference to get them.", DiagnosticSeverity.Info),
        [RuleIdentifiers.ResilienceRequiresPackage] = new("HTTP Resilience Package Recommended", "The OpenAPI specification contains x-retry-* extensions. Ensure the Microsoft.Extensions.Http.Resilience package is installed in the consuming client project.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.JwtBearerRequiresPackage] = new("Bearer authentication handler package recommended", "The OpenAPI specification has a bearer security scheme, so the generated endpoints ask for an authentication scheme named \"Bearer\". Register one - AddJwtBearer() from Microsoft.AspNetCore.Authentication.JwtBearer or AddMicrosoftIdentityWebApi() from Microsoft.Identity.Web - unless the project registers its own handler under that name.", DiagnosticSeverity.Info),
        [RuleIdentifiers.MinimalApiPackageRequired] = new("Atc.Rest.MinimalApi Package Required", "The marker file sets {0} to enabled, which needs the Atc.Rest.MinimalApi package, but it is not referenced. Add a reference to Atc.Rest.MinimalApi or set {0} to auto or disabled.", DiagnosticSeverity.Error),
        [RuleIdentifiers.LoggingRequiresPackage] = new("Microsoft.Extensions.Logging Package Required", "The marker file specifies injectLogger: true but Microsoft.Extensions.Logging.Abstractions is not available. Add a FrameworkReference to Microsoft.AspNetCore.App or a PackageReference to Microsoft.Extensions.Logging.Abstractions.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.HealthCheckPathConflict] = new("Health Check Path Conflict", "The marker file has healthChecks.enabled but the OpenAPI spec also defines paths under '{0}'. This will produce duplicate endpoint registrations. Remove the health paths from the spec or disable healthChecks in the marker file.", DiagnosticSeverity.Warning),
        [RuleIdentifiers.HealthChecksPackageRecommended] = new("Atc.Rest.HealthChecks Package Recommended", "Health checks are enabled but Atc.Rest.HealthChecks package is not referenced. Add a PackageReference to Atc.Rest.HealthChecks for structured JSON health responses with per-check details.", DiagnosticSeverity.Info),
        [RuleIdentifiers.OpenApiCoreError] = new("OpenAPI Core Parsing Error", "{0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.OpenApi20NotSupported] = new("OpenAPI 2.0 Not Supported", "{0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.OperationIdMustBeCamelCase] = new("OperationId Must Use camelCase", "{0}", DiagnosticSeverity.Warning),
