        [RuleIdentifiers.ObjectNameCasing] = new("Object Name Must Use PascalCase", "{0}", DiagnosticSeverity.Warning),
        [RuleIdentifiers.PropertyNameCasing] = new("Property Name Must Use camelCase", "{0}", DiagnosticSeverity.Warning),
        [RuleIdentifiers.EnumNameCasing] = new("Enum Name Must Use PascalCase", "{0}", DiagnosticSeverity.Warning),
        [RuleIdentifiers.ArrayPropertyMissingType] = new("Array Property Missing Data Type", "{0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.ImplicitObjectNotSupported] = new("Implicit Object Definition Not Supported", "{0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.ArrayPropertyMissingItems] = new("Array Property Missing Items Specification", "{0}", DiagnosticSeverity.Error),
        [RuleIdentifiers.PropertyKeyMissing] = new("Missing Property Key/Name", "{0}", DiagnosticSeverity.Error),
